settings.text:
{% assign rating = product.metafields.loox.avg_rating | default: 0 %}
{% assign reviews = product.metafields.loox.num_reviews | default: 0 %}

<div class="reviews_rating_html">
<a href="#reviews">

<svg xmlns="http://www.w3.org/2000/svg" width="94" height="18" viewBox="0 0 94 18" fill="none">

{% for i in (1..5) %}
{% assign star_start = i | minus: 1 | times: 19 %}
{% assign half_check = i | minus: 0.5 %}

{% if rating >= i %}

<!-- Full star -->
<path d="M{{ star_start | plus: 9 }} 0L{{ star_start | plus: 11.0206 }} 6.21885H{{ star_start | plus: 17.5595 }}L{{ star_start | plus: 12.2694 }} 10.0623L{{ star_start | plus: 14.2901 }} 16.2812L{{ star_start | plus: 9 }} 12.4377L{{ star_start | plus: 3.70993 }} 16.2812L{{ star_start | plus: 5.73056 }} 10.0623L{{ star_start | plus: 0.440492 }} 6.21885H{{ star_start | plus: 6.97937 }}L{{ star_start | plus: 9 }} 0Z" fill="#D69800"></path>

{% elsif rating >= half_check %}

<!-- Half star -->
<defs>
<clipPath id="half-star-{{ i }}">
<rect x="{{ star_start }}" y="0" width="9.5" height="18"/>
</clipPath>
</defs>

<path d="M{{ star_start | plus: 9 }} 0L{{ star_start | plus: 11.0206 }} 6.21885H{{ star_start | plus: 17.5595 }}L{{ star_start | plus: 12.2694 }} 10.0623L{{ star_start | plus: 14.2901 }} 16.2812L{{ star_start | plus: 9 }} 12.4377L{{ star_start | plus: 3.70993 }} 16.2812L{{ star_start | plus: 5.73056 }} 10.0623L{{ star_start | plus: 0.440492 }} 6.21885H{{ star_start | plus: 6.97937 }}L{{ star_start | plus: 9 }} 0Z" fill="#E5E5E5"></path>

<path d="M{{ star_start | plus: 9 }} 0L{{ star_start | plus: 11.0206 }} 6.21885H{{ star_start | plus: 17.5595 }}L{{ star_start | plus: 12.2694 }} 10.0623L{{ star_start | plus: 14.2901 }} 16.2812L{{ star_start | plus: 9 }} 12.4377L{{ star_start | plus: 3.70993 }} 16.2812L{{ star_start | plus: 5.73056 }} 10.0623L{{ star_start | plus: 0.440492 }} 6.21885H{{ star_start | plus: 6.97937 }}L{{ star_start | plus: 9 }} 0Z" fill="#D69800" clip-path="url(#half-star-{{ i }})"></path>

{% else %}

<!-- Empty star -->
<path d="M{{ star_start | plus: 9 }} 0L{{ star_start | plus: 11.0206 }} 6.21885H{{ star_start | plus: 17.5595 }}L{{ star_start | plus: 12.2694 }} 10.0623L{{ star_start | plus: 14.2901 }} 16.2812L{{ star_start | plus: 9 }} 12.4377L{{ star_start | plus: 3.70993 }} 16.2812L{{ star_start | plus: 5.73056 }} 10.0623L{{ star_start | plus: 0.440492 }} 6.21885H{{ star_start | plus: 6.97937 }}L{{ star_start | plus: 9 }} 0Z" fill="#E5E5E5"></path>

{% endif %}

{% endfor %}

</svg>

<span>
Rated {{ rating }}/5.0 |
<strong>“excellent”</strong>
</span>

</a>
</div>
